const listVisibleOwnedSkills = `-- name: ListVisibleOwnedSkills :many
WITH listed AS (
SELECT s.id, s.org_id, s.owner_kind, s.owner_project_id, s.owner_user_id, s.name,
       s.created_at,
       r.id AS revision_id, r.revision, r.description, r.skill_md,
       r.archive_digest, r.created_at AS updated_at,
       CASE $6::text
         WHEN 'name' THEN lower(s.name)
         WHEN 'created_at' THEN to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US')
         WHEN 'updated_at' THEN to_char(r.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US')
         WHEN 'owner_kind' THEN s.owner_kind
       END::text AS sort_key,
       false AS sort_is_null
FROM skills s
JOIN LATERAL (
    SELECT id, revision, description, skill_md, archive_digest, created_at
    FROM skill_revisions
    WHERE skill_id = s.id AND deleted_at IS NULL
    ORDER BY revision DESC
    LIMIT 1
) r ON true
WHERE s.org_id = $7
  AND s.deleted_at IS NULL
  AND ($8::text = '' OR s.owner_kind = $8::text)
  AND ($9::uuid IS NULL OR s.owner_project_id = $9::uuid)
  AND (
    (s.owner_kind = 'org' AND EXISTS (
      SELECT 1
      FROM org_memberships om
      WHERE om.org_id = s.org_id
        AND (
          ($10::uuid IS NOT NULL AND om.user_id = $10::uuid)
          OR ($11::uuid IS NOT NULL AND om.org_api_key_id = $11::uuid)
        )
    ))
    OR (s.owner_kind = 'project' AND EXISTS (
      SELECT 1
      FROM principal_project_authorization_roles roles
      WHERE roles.org_id = s.org_id
        AND roles.project_id = s.owner_project_id
        AND (
          ($10::uuid IS NOT NULL AND roles.user_id = $10::uuid)
          OR ($11::uuid IS NOT NULL AND roles.org_api_key_id = $11::uuid)
        )
    ))
    OR (s.owner_kind = 'user' AND s.owner_user_id = $10::uuid AND EXISTS (
      SELECT 1
      FROM org_memberships om
      WHERE om.org_id = s.org_id
        AND om.user_id = $10::uuid
    ))
  )
  AND ($12::text = '' OR s.name ILIKE $12::text ESCAPE '\')
)
SELECT id, org_id, owner_kind, owner_project_id, owner_user_id, name,
       created_at, revision_id, revision, description,
       skill_md, archive_digest, updated_at, sort_key, sort_is_null
FROM listed
WHERE $1::boolean = false
   OR ($2::boolean = false AND (sort_key, id) > ($3::text, $4::uuid))
   OR ($2::boolean = true AND (sort_key, id) < ($3::text, $4::uuid))
ORDER BY CASE WHEN $2::boolean = false THEN sort_key END ASC,
         CASE WHEN $2::boolean = true THEN sort_key END DESC,
         CASE WHEN $2::boolean = false THEN id END ASC,
         CASE WHEN $2::boolean = true THEN id END DESC
LIMIT $5::bigint
`

type ListVisibleOwnedSkillsParams struct {
	CursorSet      bool
	SortDesc       bool
	CursorKey      string
	CursorID       uuid.UUID
	RowLimit       int64
	SortField      string
	OrgID          uuid.UUID
	OwnerKind      string
	OwnerProjectID *uuid.UUID
	UserID         *uuid.UUID
	OrgApiKeyID    *uuid.UUID
	NamePattern    string
}

type ListVisibleOwnedSkillsRow struct {
	ID             uuid.UUID
	OrgID          uuid.UUID
	OwnerKind      string
	OwnerProjectID *uuid.UUID
	OwnerUserID    *uuid.UUID
	Name           string
	CreatedAt      time.Time
	RevisionID     uuid.UUID
	Revision       int32
	Description    string
	SkillMd        string
	ArchiveDigest  string
	UpdatedAt      time.Time
	SortKey        string
	SortIsNull     bool
}

func (q *Queries) ListVisibleOwnedSkills(ctx context.Context, arg ListVisibleOwnedSkillsParams) ([]ListVisibleOwnedSkillsRow, error) {
	rows, err := q.db.Query(ctx, listVisibleOwnedSkills,
		arg.CursorSet,
		arg.SortDesc,
		arg.CursorKey,
		arg.CursorID,
		arg.RowLimit,
		arg.SortField,
		arg.OrgID,
		arg.OwnerKind,
		arg.OwnerProjectID,
		arg.UserID,
		arg.OrgApiKeyID,
		arg.NamePattern,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListVisibleOwnedSkillsRow{}
	for rows.Next() {
		var i ListVisibleOwnedSkillsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.OwnerKind,
			&i.OwnerProjectID,
			&i.OwnerUserID,
			&i.Name,
			&i.CreatedAt,
			&i.RevisionID,
			&i.Revision,
			&i.Description,
			&i.SkillMd,
			&i.ArchiveDigest,
			&i.UpdatedAt,
			&i.SortKey,
			&i.SortIsNull,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockSkill = `-- name: LockSkill :one
SELECT id
FROM skills
WHERE org_id = $1
  AND id = $2
  AND deleted_at IS NULL
FOR UPDATE
`

type LockSkillParams struct {
	OrgID uuid.UUID
	ID    uuid.UUID
}

func (q *Queries) LockSkill(ctx context.Context, arg LockSkillParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockSkill, arg.OrgID, arg.ID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const nextSkillRevision = `-- name: NextSkillRevision :one
SELECT (COALESCE(MAX(revision), 0) + 1)::int AS revision
FROM skill_revisions
WHERE skill_id = $1
`

type NextSkillRevisionParams struct {
	SkillID uuid.UUID
}

// @sqlc-vet-disable skill-revisions-deleted-at
// Counts soft-deleted revisions too: revision numbers are never reused, and
// UNIQUE (skill_id, revision) spans deleted rows.
func (q *Queries) NextSkillRevision(ctx context.Context, arg NextSkillRevisionParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextSkillRevision, arg.SkillID)
	var revision int32
	err := row.Scan(&revision)
	return revision, err
}

const skillAvailableToProject = `-- name: SkillAvailableToProject :one
SELECT EXISTS (
  SELECT 1
  FROM skills s
  WHERE s.org_id = $1
    AND s.id = $2
    AND s.deleted_at IS NULL
    AND (
      (s.owner_kind = 'project' AND s.owner_project_id = $3::uuid)
      OR EXISTS (
        SELECT 1
        FROM skill_grants sg
        WHERE sg.org_id = s.org_id
          AND sg.skill_id = s.id
          AND sg.target_project_id = $3::uuid
      )
    )
)::boolean AS available
`

type SkillAvailableToProjectParams struct {
	OrgID     uuid.UUID
	SkillID   uuid.UUID
	ProjectID uuid.UUID
}

func (q *Queries) SkillAvailableToProject(ctx context.Context, arg SkillAvailableToProjectParams) (bool, error) {
	row := q.db.QueryRow(ctx, skillAvailableToProject, arg.OrgID, arg.SkillID, arg.ProjectID)
	var available bool
	err := row.Scan(&available)
	return available, err
}

const skillHasActiveAgentReferences = `-- name: SkillHasActiveAgentReferences :one
SELECT EXISTS (
  SELECT 1
  FROM agents agent
  JOIN agent_configs config
    ON config.project_id = agent.project_id
   AND config.id = agent.current_config_id
  WHERE agent.org_id = $1
    AND agent.state = 'active'
    AND config.compiled_definition->'skills' @> jsonb_build_array(jsonb_build_object('public_id', $2::text))
) AS has_active_agent_references
`

type SkillHasActiveAgentReferencesParams struct {
	OrgID         uuid.UUID
	SkillPublicID string
}

// Compiled agent configs reference skills by public id, so the caller passes
// the encoded skill id rather than the raw uuid.
func (q *Queries) SkillHasActiveAgentReferences(ctx context.Context, arg SkillHasActiveAgentReferencesParams) (bool, error) {
	row := q.db.QueryRow(ctx, skillHasActiveAgentReferences, arg.OrgID, arg.SkillPublicID)
	var has_active_agent_references bool
	err := row.Scan(&has_active_agent_references)
	return has_active_agent_references, err
}
